<?php
namespace Nakhostin\PerformanceEngine\CSS;
final class CriticalCSSStorage { public const OPTION = 'npe_critical_css'; public function save( CriticalCSSManifest $manifest ): bool { if ( ! $manifest->is_valid() ) { return false; } $data = $manifest->to_array(); $all = get_option( self::OPTION, array() ); $all = is_array( $all ) ? $all : array(); $all[ sanitize_key( $data['page_signature'] ) ] = $data; return update_option( self::OPTION, array_slice( $all, -100, null, true ), false ); } public function get( string $signature ): ?CriticalCSSManifest { $all = get_option( self::OPTION, array() ); $data = is_array( $all ) ? ( $all[ sanitize_key( $signature ) ] ?? null ) : null; $manifest = is_array( $data ) ? new CriticalCSSManifest( $data ) : null; return $manifest && $manifest->is_valid() ? $manifest : null; } public function flush(): bool { return delete_option( self::OPTION ); } }
